insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001831', 'responsible for', '/rɪˈspɑːnsəbəl fɔːr/', 'phrase', 'responsável por', 'She is responsible for the marketing budget.', 'Ela é responsável pelo orçamento de marketing.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001832', 'capable of', '/ˈkeɪpəbəl ʌv/', 'phrase', 'capaz de', 'He is capable of solving complex problems.', 'Ele é capaz de resolver problemas complexos.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001833', 'dependent on', '/dɪˈpendənt ɒn/', 'phrase', 'dependente de', 'The company''s success is dependent on good management.', 'O sucesso da empresa depende de uma boa gestão.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001834', 'committed to', '/kəˈmɪtɪd tuː/', 'phrase', 'comprometido com', 'The team is committed to meeting the deadline.', 'A equipe está comprometida em cumprir o prazo.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001835', 'accustomed to', '/əˈkʌstəmd tuː/', 'phrase', 'acostumado a', 'She is accustomed to working long hours.', 'Ela está acostumada a trabalhar muitas horas.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001836', 'aware of', '/əˈwer ʌv/', 'phrase', 'ciente de', 'He was not aware of the new policy.', 'Ele não estava ciente da nova política.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001837', 'concerned about', '/kənˈsɜːrnd əˈbaʊt/', 'phrase', 'preocupado com', 'Investors are concerned about the market.', 'Os investidores estão preocupados com o mercado.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001838', 'involved in', '/ɪnˈvɑːlvd ɪn/', 'phrase', 'envolvido em', 'She is deeply involved in the negotiation.', 'Ela está profundamente envolvida na negociação.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001839', 'keen on', '/kiːn ɒn/', 'phrase', 'entusiasmado com', 'He is keen on starting his own business.', 'Ele está entusiasmado em começar seu próprio negócio.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001840', 'suitable for', '/ˈsuːtəbəl fɔːr/', 'phrase', 'adequado para', 'This course is suitable for beginners.', 'Este curso é adequado para iniciantes.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001841', 'insist on', '/ɪnˈsɪst ɒn/', 'phrase', 'insistir em', 'She insisted on paying the bill.', 'Ela insistiu em pagar a conta.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001842', 'rely on', '/rɪˈlaɪ ɒn/', 'phrase', 'depender de', 'We rely on data to make decisions.', 'Nós dependemos de dados para tomar decisões.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001843', 'consist of', '/kənˈsɪst ʌv/', 'phrase', 'consistir em', 'The exam consists of three parts.', 'A prova consiste em três partes.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001844', 'deal with', '/diːl wɪð/', 'phrase', 'lidar com', 'He knows how to deal with difficult clients.', 'Ele sabe como lidar com clientes difíceis.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001845', 'apply for', '/əˈplaɪ fɔːr/', 'phrase', 'candidatar-se a', 'She decided to apply for the scholarship.', 'Ela decidiu se candidatar à bolsa de estudos.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001846', 'apologize for', '/əˈpɑːlədʒaɪz fɔːr/', 'phrase', 'desculpar-se por', 'He apologized for the delay.', 'Ele se desculpou pelo atraso.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001847', 'believe in', '/bɪˈliːv ɪn/', 'phrase', 'acreditar em', 'She believes in hard work and honesty.', 'Ela acredita em trabalho duro e honestidade.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001848', 'succeed in', '/səkˈsiːd ɪn/', 'phrase', 'ter sucesso em', 'They succeeded in reducing costs by ten percent.', 'Eles tiveram sucesso em reduzir os custos em dez por cento.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001849', 'specialize in', '/ˈspeʃəlaɪz ɪn/', 'phrase', 'especializar-se em', 'This lawyer specializes in corporate law.', 'Este advogado se especializa em direito empresarial.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001850', 'benefit from', '/ˈbenɪfɪt frʌm/', 'phrase', 'beneficiar-se de', 'Small businesses can benefit from this new law.', 'Pequenas empresas podem se beneficiar dessa nova lei.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001851', 'access to', '/ˈækses tuː/', 'phrase', 'acesso a', 'Employees have access to free training.', 'Os funcionários têm acesso a treinamento gratuito.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001852', 'reason for', '/ˈriːzən fɔːr/', 'phrase', 'motivo para', 'There is no clear reason for the delay.', 'Não há um motivo claro para o atraso.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001853', 'solution to', '/səˈluːʃən tuː/', 'phrase', 'solução para', 'They found a solution to the problem.', 'Eles encontraram uma solução para o problema.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001854', 'relationship between', '/rɪˈleɪʃənʃɪp bɪˈtwiːn/', 'phrase', 'relação entre', 'There is a strong relationship between sleep and productivity.', 'Há uma forte relação entre sono e produtividade.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001855', 'increase in', '/ˈɪnkriːs ɪn/', 'phrase', 'aumento em', 'There was a sharp increase in sales last month.', 'Houve um forte aumento nas vendas no mês passado.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001856', 'impact on', '/ˈɪmpækt ɒn/', 'phrase', 'impacto em', 'The new policy had a big impact on employees.', 'A nova política teve um grande impacto sobre os funcionários.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001857', 'approach to', '/əˈproʊtʃ tuː/', 'phrase', 'abordagem para', 'The team took a new approach to the project.', 'A equipe adotou uma nova abordagem para o projeto.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001858', 'demand for', '/dɪˈmænd fɔːr/', 'phrase', 'demanda por', 'There is a growing demand for remote jobs.', 'Há uma demanda crescente por empregos remotos.', 'B2', array['grammar', 'prepositions']),
('30000000-0000-0000-0000-000000001859', 'interest in', '/ˈɪntrəst ɪn/', 'phrase', 'interesse em', 'She has always shown interest in design.', 'Ela sempre demonstrou interesse em design.', 'B2', array['grammar', 'prepositions']),
