('20000000-0000-0000-0000-000000000306', 'matching', 6, '{"pairs": [{"left": "responsible for", "right": "responsável por"}, {"left": "capable of", "right": "capaz de"}, {"left": "dependent on", "right": "dependente de"}, {"left": "committed to", "right": "comprometido com"}, {"left": "accustomed to", "right": "acostumado a"}, {"left": "aware of", "right": "ciente de"}]}'),
('20000000-0000-0000-0000-000000000306', 'fill_blank', 7, '{"sentence": "The team is ___ meeting the deadline.", "options": ["committed to", "aware of", "capable of"], "correct": "committed to", "translation": "A equipe está comprometida em cumprir o prazo."}'),
('20000000-0000-0000-0000-000000000306', 'fill_blank', 8, '{"sentence": "She is ___ working long hours.", "options": ["accustomed to", "dependent on", "responsible for"], "correct": "accustomed to", "translation": "Ela está acostumada a trabalhar muitas horas."}'),
('20000000-0000-0000-0000-000000000306', 'word_order', 9, '{"words": ["The", "company''s", "success", "is", "dependent", "on", "good", "management"], "correct_sentence": "The company''s success is dependent on good management", "translation": "O sucesso da empresa depende de uma boa gestão"}'),
('20000000-0000-0000-0000-000000000306', 'word_order', 10, '{"words": ["He", "was", "not", "aware", "of", "the", "new", "policy"], "correct_sentence": "He was not aware of the new policy", "translation": "Ele não estava ciente da nova política"}'),
('20000000-0000-0000-0000-000000000306', 'reading', 11, '{"passage": "Many adjectives in English are always followed by the same preposition. You are responsible for a task, capable of an action, dependent on something, committed to a goal, accustomed to a routine, and aware of a fact. Getting these prepositions right is a key sign of fluency at an advanced level.", "translation": "Muitos adjetivos em inglês são sempre seguidos da mesma preposição. Você é responsible for uma tarefa, capable of uma ação, dependent on algo, committed to um objetivo, accustomed to uma rotina, e aware of um fato. Acertar essas preposições é um sinal importante de fluência em nível avançado.", "question": "What is described as a key sign of fluency, according to the text?", "options": ["Using long sentences", "Getting these prepositions right", "Speaking fast"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000306', 'listening', 12, '{"audio_text": "She is responsible for the marketing budget. He is capable of solving complex problems. The company''s success is dependent on good management.", "question": "What is she responsible for, according to the audio?", "options": ["The marketing budget", "The sales team", "The office"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000306', 'dictation', 13, '{"audio_text": "She is responsible for the marketing budget.", "expected": "She is responsible for the marketing budget."}'),
('20000000-0000-0000-0000-000000000306', 'typing', 14, '{"prompt_pt": "Traduza: ''Ele é responsável pelo projeto e está comprometido em terminá-lo a tempo.''", "expected": "He is responsible for the project and is committed to finishing it on time.", "ai_review": true}'),

