('20000000-0000-0000-0000-000000000307', 'multiple_choice', 4, '{"question": "Investors are ___ the market.", "audio_text": null, "options": ["concerned about", "keen on", "involved in"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000307', 'multiple_choice', 5, '{"question": "We ___ data to make decisions.", "audio_text": null, "options": ["rely on", "insist on", "consist of"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000307', 'matching', 6, '{"pairs": [{"left": "concerned about", "right": "preocupado com"}, {"left": "involved in", "right": "envolvido em"}, {"left": "keen on", "right": "entusiasmado com"}, {"left": "suitable for", "right": "adequado para"}, {"left": "insist on", "right": "insistir em"}, {"left": "rely on", "right": "depender de"}]}'),
('20000000-0000-0000-0000-000000000307', 'fill_blank', 7, '{"sentence": "She is deeply ___ the negotiation.", "options": ["involved in", "keen on", "suitable for"], "correct": "involved in", "translation": "Ela está profundamente envolvida na negociação."}'),
('20000000-0000-0000-0000-000000000307', 'fill_blank', 8, '{"sentence": "This course is ___ beginners.", "options": ["suitable for", "concerned about", "rely on"], "correct": "suitable for", "translation": "Este curso é adequado para iniciantes."}'),
('20000000-0000-0000-0000-000000000307', 'word_order', 9, '{"words": ["He", "is", "keen", "on", "starting", "his", "own", "business"], "correct_sentence": "He is keen on starting his own business", "translation": "Ele está entusiasmado em começar seu próprio negócio"}'),
('20000000-0000-0000-0000-000000000307', 'word_order', 10, '{"words": ["She", "insisted", "on", "paying", "the", "bill"], "correct_sentence": "She insisted on paying the bill", "translation": "Ela insistiu em pagar a conta"}'),
('20000000-0000-0000-0000-000000000307', 'reading', 11, '{"passage": "More adjectives and verbs follow fixed prepositions: you can be concerned about a problem, involved in a project, keen on an idea, or say something is suitable for a purpose. Verbs work the same way: people insist on doing things their way, and businesses rely on data to make good decisions.", "translation": "Mais adjetivos e verbos seguem preposições fixas: você pode estar concerned about um problema, involved in um projeto, keen on uma ideia, ou dizer que algo é suitable for um propósito. Verbos funcionam da mesma forma: pessoas insist on fazer as coisas do jeito delas, e empresas rely on dados para tomar boas decisões.", "question": "What do businesses rely on to make good decisions, according to the text?", "options": ["Intuition", "Data", "Luck"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000307', 'listening', 12, '{"audio_text": "Investors are concerned about the market. She is deeply involved in the negotiation. We rely on data to make decisions.", "question": "What are investors concerned about, according to the audio?", "options": ["The market", "The negotiation", "The data"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000307', 'dictation', 13, '{"audio_text": "We rely on data to make decisions.", "expected": "We rely on data to make decisions."}'),
('20000000-0000-0000-0000-000000000307', 'typing', 14, '{"prompt_pt": "Traduza: ''Ela está entusiasmada com a nova oportunidade, mas está preocupada com o salário.''", "expected": "She is keen on the new opportunity, but concerned about the salary.", "ai_review": true}'),

