('20000000-0000-0000-0000-000000000308', 'multiple_choice', 4, '{"question": "The exam ___ three parts.", "audio_text": null, "options": ["consists of", "deals with", "applies for"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000308', 'multiple_choice', 5, '{"question": "He knows how to ___ difficult clients.", "audio_text": null, "options": ["deal with", "believe in", "succeed in"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000308', 'matching', 6, '{"pairs": [{"left": "consist of", "right": "consistir em"}, {"left": "deal with", "right": "lidar com"}, {"left": "apply for", "right": "candidatar-se a"}, {"left": "apologize for", "right": "desculpar-se por"}, {"left": "believe in", "right": "acreditar em"}, {"left": "succeed in", "right": "ter sucesso em"}]}'),
('20000000-0000-0000-0000-000000000308', 'fill_blank', 7, '{"sentence": "She decided to ___ the scholarship.", "options": ["apply for", "apologize for", "consist of"], "correct": "apply for", "translation": "Ela decidiu se candidatar à bolsa de estudos."}'),
('20000000-0000-0000-0000-000000000308', 'fill_blank', 8, '{"sentence": "They ___ reducing costs by ten percent.", "options": ["succeeded in", "believed in", "dealt with"], "correct": "succeeded in", "translation": "Eles tiveram sucesso em reduzir os custos em dez por cento."}'),
('20000000-0000-0000-0000-000000000308', 'word_order', 9, '{"words": ["He", "apologized", "for", "the", "delay"], "correct_sentence": "He apologized for the delay", "translation": "Ele se desculpou pelo atraso"}'),
('20000000-0000-0000-0000-000000000308', 'word_order', 10, '{"words": ["She", "believes", "in", "hard", "work", "and", "honesty"], "correct_sentence": "She believes in hard work and honesty", "translation": "Ela acredita em trabalho duro e honestidade"}'),
('20000000-0000-0000-0000-000000000308', 'reading', 11, '{"passage": "Verbs also carry fixed prepositions. A test can consist of several parts, and a good manager knows how to deal with difficult situations. When looking for a job, people apply for positions, and if something goes wrong, they apologize for their mistakes. Those who believe in hard work often succeed in reaching their goals.", "translation": "Verbos também carregam preposições fixas. Um teste pode consist of várias partes, e um bom gerente sabe deal with situações difíceis. Ao procurar emprego, as pessoas apply for vagas, e se algo dá errado, elas apologize for seus erros. Quem believe in trabalho duro costuma succeed in alcançar seus objetivos.", "question": "According to the text, what do people do when looking for a job?", "options": ["They apologize for positions", "They apply for positions", "They deal with positions"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000308', 'listening', 12, '{"audio_text": "The exam consists of three parts. He knows how to deal with difficult clients. She decided to apply for the scholarship.", "question": "How many parts does the exam consist of, according to the audio?", "options": ["Two", "Three", "Four"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000308', 'dictation', 13, '{"audio_text": "He knows how to deal with difficult clients.", "expected": "He knows how to deal with difficult clients."}'),
('20000000-0000-0000-0000-000000000308', 'typing', 14, '{"prompt_pt": "Traduza: ''Ela se candidatou à vaga e acredita que vai ter sucesso na entrevista.''", "expected": "She applied for the job and believes she will succeed in the interview.", "ai_review": true}'),

