('20000000-0000-0000-0000-000000000309', 'multiple_choice', 4, '{"question": "This lawyer ___ corporate law.", "audio_text": null, "options": ["specializes in", "benefits from", "accesses to"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000309', 'multiple_choice', 5, '{"question": "Employees have ___ free training.", "audio_text": null, "options": ["access to", "reason for", "solution to"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000309', 'matching', 6, '{"pairs": [{"left": "specialize in", "right": "especializar-se em"}, {"left": "benefit from", "right": "beneficiar-se de"}, {"left": "access to", "right": "acesso a"}, {"left": "reason for", "right": "motivo para"}, {"left": "solution to", "right": "solução para"}, {"left": "relationship between", "right": "relação entre"}]}'),
('20000000-0000-0000-0000-000000000309', 'fill_blank', 7, '{"sentence": "They found a ___ the problem.", "options": ["solution to", "reason for", "access to"], "correct": "solution to", "translation": "Eles encontraram uma solução para o problema."}'),
('20000000-0000-0000-0000-000000000309', 'fill_blank', 8, '{"sentence": "There is a strong ___ sleep and productivity.", "options": ["relationship between", "solution to", "benefit from"], "correct": "relationship between", "translation": "Há uma forte relação entre sono e produtividade."}'),
('20000000-0000-0000-0000-000000000309', 'word_order', 9, '{"words": ["Small", "businesses", "can", "benefit", "from", "this", "new", "law"], "correct_sentence": "Small businesses can benefit from this new law", "translation": "Pequenas empresas podem se beneficiar dessa nova lei"}'),
('20000000-0000-0000-0000-000000000309', 'word_order', 10, '{"words": ["There", "is", "no", "clear", "reason", "for", "the", "delay"], "correct_sentence": "There is no clear reason for the delay", "translation": "Não há um motivo claro para o atraso"}'),
('20000000-0000-0000-0000-000000000309', 'reading', 11, '{"passage": "Nouns also require specific prepositions in formal English. A professional can specialize in a field, and a company might benefit from a new opportunity. Employees expect access to good resources, and every problem needs a clear reason for its cause and, ideally, a solution to fix it. Researchers often study the relationship between two different factors.", "translation": "Substantivos também exigem preposições específicas no inglês formal. Um profissional pode specialize in uma área, e uma empresa pode benefit from uma nova oportunidade. Funcionários esperam access to bons recursos, e todo problema precisa de um reason for claro para sua causa e, idealmente, uma solution to para resolvê-lo. Pesquisadores costumam estudar a relationship between dois fatores diferentes.", "question": "What do employees expect, according to the text?", "options": ["Access to good resources", "A solution to every problem", "A relationship between factors"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000309', 'listening', 12, '{"audio_text": "This lawyer specializes in corporate law. Employees have access to free training. They found a solution to the problem.", "question": "What does the lawyer specialize in, according to the audio?", "options": ["Criminal law", "Corporate law", "Family law"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000309', 'dictation', 13, '{"audio_text": "They found a solution to the problem.", "expected": "They found a solution to the problem."}'),
